WFJ.Data.add("gossip", {
  ["490250110afbfc5d"] = { "Ehilà, {class}! Pare che l'⟦Horde=Orda⟧ abbia raccolto l'ultima parte della sua roba, e ora la loro e la nostra vengono spedite a ⟦Silithus=Silitus⟧ proprio mentre parliamo. Mi dicono che arriverà in meno di un giorno, e poi qualcuno potrà suonare quel grosso gong vicino ai cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per dare inizio alla guerra.", "." },
  ["490e2b149820cf8a"] = { "Voglio acquistare da te dell'Accelerante Arcano.", "." },
  ["4913da2e90d8a681"] = { "Né tu né io potremmo mai immaginare il dolore che prova chi si vede strappare l'anima dal corpo. Non sono morti, e non sono affatto vivi. Vagano invece per la terra, servi di chi li vincola a questo mondo.\n\nLord Razelikh, signore demoniaco di queste terre, li ha resi tutti schiavi. Nove li ha presi per sé, collocando pietre di vincolo vicino al Portale Oscuro. Gli altri nove li ha divisi fra i suoi sottoposti.", "." },
  ["491bd43b002a6e73"] = { "Di certo non è stato Mot a mandarti da me? Lui sa come stanno le cose. Non sei ancora in grado di capire ciò che potrei insegnarti. Va' da mio figlio Mot, proprio lì fuori, e finisci l'addestramento con lui.", "." },
  ["491e13730759a957"] = { "Nascosta nel ⟦Mage Quarter=Quartiere dei Maghi⟧ c'è una piccola bottega chiamata Alchemy Needs. Attraversando il ⟦Mage Quarter=Quartiere dei Maghi⟧ vedrai ogni sorta di negozi strani, ma se resti lungo il bordo esterno la troverai di sicuro.", "." },
  ["49212b505322a208"] = { "Persino i demoni sanno provare paura...", "." },
  ["492a3b94c57c26a1"] = { "Ho moltissimo lavoro da fare. Sei qui per aiutarmi con le mie ricerche?", "." },
  ["4938875a67b733da"] = { "La ⟦Coldtooth Mine=Miniera di Dentefreddo⟧ appartiene all'⟦Alliance=Alleanza⟧.", "." },
  ["493f07ec33ac4a6d"] = { "%s nota le tue vili tattiche di battaglia e fugge dallo scontro.", "." },
  ["4945bb4efa119e5e"] = { "EHI! EHI, TU! {race}! Tirami fuori di qui!", "." },
  ["494667f461e28050"] = { "Hai qualcosa che mi serve, Astor. E adesso me lo prendo.", "." },
  ["494b2ae0ba9466de"] = { "Ascolta attentamente, {name}, perché ho molto sapere da trasmetterti.", "." },
  ["4951c70f5f63c2f3"] = { "Non c'è speranza!", "." },
  ["49530a1cc7ae9b6c"] = { "L'anziano Corno Fiero si gode il panorama sopra Mulgore, a ⟦Thunder Bluff=Picco del Tuono⟧.", "." },
  ["495312bad048c901"] = { "La settimana scorsa ne ho preso uno enorme, aveva tre occhi!", "." },
  ["495657b7318a93ea"] = { "%s scambia qualche parola sommessa con {name} e <gli/le> consegna un piccolo oggetto.", "." },
  ["495b338f744b4f32"] = { "Mi serve un'altra serie di attrezzi.", "." },
  ["495f67ce207dbe2a"] = { "%s assorbe l'energia del totem e la reindirizza sotto forma di impulso antimagia.", "." },
  ["496072da3e359a49"] = { "CHE IL FUOCO VI PURIFICHI!", "." },
  ["4971c2da59ea5f91"] = { "|cffffff00La Torre di Levante è stata conquistata dall'⟦Horde=Orda⟧!|r", "." },
  ["49725f272722d8bd"] = { "Urla il tuo ultimo respiro!", "." },
  ["4979177b05e43363"] = { "Niente male, per <un/una> principiante! Immagino che non mi costi nulla mostrarti un paio di cose...", "." },
  ["497a07782fe198e9"] = { "Dov'è l'anziana Preda Cielo?", "." },
  ["497f3fc6b20f5266"] = { "Cosa puoi insegnarmi?", "." },
  ["497f560353808768"] = { "Sogno, {name}... oh sì, sogno. Nei miei sogni muoio mille volte in mille modi diversi. Qualcuno chiamerebbe incubi i sogni come i miei. IO NO! Nei sogni muoio nel cuore della battaglia. Per ogni mia singola morte, diecimila nemici dell'⟦Horde=Orda⟧ cadono davanti a me. È glorioso!", "." },
  ["497fc36e3df7a504"] = { "Non so come facciano... quelle cassette della posta devono essere portali magici o roba simile. Pensa che vedo gente radunata tutto il giorno attorno alla cassetta della posta accanto alla banca, che tira fuori spade, scudi e armature di ogni tipo da quella scatoletta!", "." },
  ["499b5330403da3ef"] = { "Centro! Quel dannato nano non sa di cosa parla. L'unico difetto del fucile di Grumlar è la mira di Grumlar.", "." },
  ["49abe2c645224d52"] = { "L'ultimo santuario di fanatici impazziti. È lì che creano le loro uniformi scarlatte, intrise di magia dal filo scarlatto incantato!\n\nA Stratholme, avventuriero!", "." },
  ["49ad68a926009f2f"] = { "%s si lascia sfuggire una risata sinistra.", "." },
  ["49af4aa89722ad27"] = { "Molti non sono d'accordo su questo punto. Io credo che la chiave sia la semplice comunicazione. I canti del vento ci arrivavano così chiari quando gli spiriti erano ancora qui. Da quando se ne sono andati è calato il silenzio, e il nostro potere di plasmavento si è indebolito.\n\nEppure alcuni di noi sentono ancora qualcosa. Un tono sommesso. Frammenti di una melodia. Chi riesce ancora a sentire e a vedere nei piani elementali deve diventare più forte. Credo che questa sia la chiave della nostra salvezza.", "." },
  ["49b024a7c8b28308"] = { "Sai cucinare? Anch'io! C'è una ricetta che puoi insegnarmi?", "." },
  ["49b437f13d0aa6e4"] = { "Bevute gratis al Blue Recluse!", "." },
  ["49b53774826c51ce"] = { "Porta la Tattered Note a ⟦Rau Cliffrunner=Rau Scalarupi⟧, a ⟦Thousand Needles=Millepicchi⟧.", "." },
  ["49b72426ab41b58e"] = { "Raaarrrrggghhh! Veniamo a prenderti!", "." },
  ["49b9c272e750dd0c"] = { "La nonna diceva sempre che non c'era cosa più bella al mondo di una fetta calda e fragrante di torta di ciliegie fresca, fatta in casa.", "." },
  ["49c08fce7bcffaf7"] = { "Glorioso davvero, Maltrake. Pare che il mio piano abbia funzionato alla perfezione. Non sei d'accordo, mortale?", "." },
  ["49d6bc106a788afb"] = { "%s scompare nella palude.", "." },
  ["49d70cb91e3182b1"] = { "%s tira un sospiro di sollievo.", "." },
  ["49da27023461b0a1"] = { "Ti prego, fai come ti dico, {name}.", "." },
  ["49e150e92d8dff51"] = { "Benvenut<o/a> alla Tenuta di Ambraquieta. Se ti interessa acquistare una cavalcatura, mio marito Veron sarà più che felice di aiutarti a scegliere la bestia giusta. Se invece cerchi avventure, be', un aiuto da queste parti ci farebbe proprio comodo...", "." },
  ["49e5578d03825cda"] = { "Addestrami nelle vie della bestia.", "." },
  ["49e7f9b9be13657f"] = { "Esala l'ultimo respiro!", "." },
  ["49e92c34807026b1"] = { "Preparatevi alla battaglia, mie creature.", "." },
  ["49ea3b4ef4b211a1"] = { "Le rovine di ⟦Dire Maul=Maglio Infausto⟧ sorgono nel cuore di Feralas.", "." },
  ["49eef3288d3da435"] = { "Se mi tocchi ancora, sarà l'ultima cosa che toccherai!", "." },
  ["49f571bee726d514"] = { "Torno alla Colonia, Tinkee. Mi serve un Uovoscilloscopio!", "." },
  ["49f646642d40903e"] = { "Il futuro riserva molta morte e incertezza, non diversamente dal passato.", "." },
  ["49f66c6d1cecc229"] = { "Ho pagato il tuo prezzo, ⟦Gloom'rel=Furien'rel⟧. Ora insegnami i tuoi segreti!", "." },
  ["49f9248ee79d3593"] = { "Quelle bestie schifose sono dappertutto.\n\nSe preferisci cacciare all'aperto, la maggior parte la troverai attorno a ⟦Plaguewood=Malaselva⟧ e ⟦Terrordale=Valterrore⟧, con una buona concentrazione nella Galleria dell'Orrore Brulicante. È probabile che compaiano anche in quasi ogni accampamento del Flagello nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.\n\nSe invece ami esplorare i sotterranei con tenacia, ne troverai parecchie a Stratholme e alcune della varietà necrodemone a Scholomance.", "." },
})
